using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Blackrazor (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class Blackrazor2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("blackrazor", null, 0, MagicItemType.Weapon, ItemRarity.Legendary, true, ContentSource.RealmForge,
			Magic(Effect(MagicEffectKind.AttackAndDamage, 3)),
			("Lama nera", "Arma (spadone), leggendaria (richiede sintonia con una creatura di allineamento non legale)",
			"Nascosta nei sotterranei del Montagna della Piuma Bianca, questa lama risplende come un frammento di cielo notturno pieno di stelle; il fodero nero è ornato di schegge di ossidiana.\n\nIl personaggio ottiene un bonus di +3 ai tiri per colpire e ai danni effettuati con quest'arma magica.\n\n***Divorare anime.*** Quando il personaggio riduce una creatura a 0 punti ferita con la spada, la uccide e ne divora l'anima, a meno che non sia un costrutto o un non morto; una creatura la cui anima è stata divorata può tornare in vita solo con un *desiderio*. Ogni volta che divora un'anima, la spada concede al personaggio punti ferita temporanei pari ai punti ferita massimi della creatura uccisa, che svaniscono dopo 24 ore. Finché ha questi punti ferita temporanei e impugna la spada, il personaggio dispone di vantaggio ai tiri per colpire, ai tiri salvezza e alle prove di caratteristica. Se colpisce un non morto, il personaggio subisce 1d10 danni necrotici e il bersaglio recupera 1d10 punti ferita; se questi danni lo riducono a 0 punti ferita, la spada divora la sua anima.\n\n***Cacciatrice di anime.*** Mentre impugna la spada, il personaggio percepisce la presenza delle creature di taglia Minuscola o superiore entro 18 metri da lui che non siano costrutti o non morti, e non può essere affascinato né spaventato. Una volta al giorno la spada può lanciare *velocità* sul personaggio: decide lei quando farlo e mantiene la concentrazione al suo posto.\n\n***Senzienza.*** Lama nera è un'arma senziente caotica neutrale con Intelligenza 17, Saggezza 10 e Carisma 19. Ha udito e scurovisione fino a 36 metri. Può parlare, leggere e capire il Comune, comunica telepaticamente con chi la impugna e, mentre il personaggio è in sintonia con essa, capisce tutti i linguaggi che lui conosce. La sua voce è profonda e rimbombante.\n\n***Personalità.*** Parla con tono imperioso, come chi è abituato a essere obbedito. Il suo scopo è consumare anime, di chiunque siano, compresa quella di chi la impugna: crede che tutta la materia e l'energia siano nate da un vuoto di energia negativa e che un giorno vi torneranno, e vuole affrettare quel momento. Nonostante il suo nichilismo prova uno strano legame con Onda e Maglio soverchiante, le altre due armi rinchiuse sotto il Montagna della Piuma Bianca, e vorrebbe vederle riunite in battaglia, anche se litiga furiosamente con Maglio soverchiante e trova Onda noiosa. Se passa tre giorni o più senza divorare un'anima, al tramonto successivo entra in conflitto con chi la impugna.", null),
			("Blackrazor", "Weapon (greatsword), legendary (requires attunement by a creature of non-lawful alignment)",
			"Hidden in the dungeon of White Plume Mountain, this blade shines like a piece of night sky full of stars; its black scabbard is set with shards of obsidian.\n\nYou gain a +3 bonus to attack and damage rolls made with this magic weapon.\n\n***Devour Soul.*** When you reduce a creature to 0 hit points with the sword, it slays the creature and devours its soul, unless it is a construct or an undead; a creature whose soul was devoured can be brought back to life only by a *wish*. Each time it devours a soul, the sword gives you temporary hit points equal to the slain creature's hit point maximum, which fade after 24 hours. While you have them and hold the sword, you have advantage on attack rolls, saving throws and ability checks. If you hit an undead with it, you take 1d10 necrotic damage and the target regains 1d10 hit points; if that damage drops you to 0 hit points, the sword devours your soul.\n\n***Soul Hunter.*** While holding the sword, you sense the presence of Tiny or larger creatures within 60 feet of you that aren't constructs or undead, and you can't be charmed or frightened. Once per day the sword can cast *haste* on you: it chooses when, and it concentrates on the spell for you.\n\n***Sentience.*** Blackrazor is a sentient chaotic neutral weapon with Intelligence 17, Wisdom 10 and Charisma 19. It has hearing and darkvision out to 120 feet. It can speak, read and understand Common, communicates telepathically with its wielder and, while you are attuned to it, understands every language you know. Its voice is deep and echoing.\n\n***Personality.*** It speaks imperiously, like one used to being obeyed. Its purpose is to consume souls, anyone's, its wielder's included: it believes all matter and energy came from a void of negative energy and will return to it one day, and it wants to hurry that along. Despite its nihilism it feels a strange bond with Wave and Whelm, the two other weapons locked under White Plume Mountain, and wants them reunited in battle, though it argues bitterly with Whelm and finds Wave dull. If it goes three days or more without devouring a soul, it comes into conflict with its wielder at the next sunset.", null));
	}
}
